custom_css:
/* 底栏QR按键隐藏 */
#send_form:hover #qr--bar {    
    height: 40px;    
    transition: all 0.5s ease;
}

#qr--bar {    
    height: 0.1px;
}

code span.comment {
    color: #999;
    font-style: italic;
}

body {
    font-family: 'ZhuqueFangsong', serif;
    line-height: 1.5;
    font-weight: 300; 
}

@font-face {
    font-family: 'ZhuqueFangsong';
    src: url("http://sharkpan.xyz/f/24j6iQ/%E4%B8%AD%E6%96%87%20-%20Huiwen.otf") format('truetype'); /* 修改为新的字体链接 */
    font-weight: 200; /* 设置字体粗细为400 */
    font-style: normal;
}

/* 高亮样式 */
code span.keyword {
    color: #007BFF; /* 关键字颜色 */
    font-weight: bold;
}

code span.string {
    color: #d14;
}

* {
    --black30a: rgb(255 255 255 / 30%);
    --black50a: rgb(255 255 255 / 50%);
    --black70a: rgb(255 255 255 / %);
    --white20a: rgb(255 255 255 / 20%);
    --white30a: rgb(255 255 255 / 30%);
    --white50a: rgb(255 255 255 / 50%);
    --white70a: rgba(20 20 34/ 90%);
    --grey30: rgb(255 255 255);
    --grey30a: rgb(255 255 255 / 30%);
    --grey7070a: rgb(255 255 255 / 70%);
}

/* 添加占位符的样式 */
textarea::placeholder, input[type="text"]::placeholder {
    font-family: 'ZhuqueFangsong', serif;
    color: #999; /* 灰色占位符 */
    font-weight: 300; /* 更细的占位符字体 */
    font-size: 14px; /* 占位符稍小 */
}

/* 聚焦时样式 */
textarea:focus, input[type="text"]:focus {
    border-color: #000; /* 聚焦时边框保持黑色 */
    background-color: #f7f7f7; /* 微微变浅的灰白色背景 */
    box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.5); /* 更深的阴影效果 */
}

textarea, input[type="text"] {
    font-family: 'ZhuqueFangsong', serif; /* 嵌入字体 */
    font-size: 16px; /* 字体大小 */
    font-weight: 300; /* 字体粗细 */
    line-height: 1.6; /* 行高 */
    color: #000; /* 黑色字体 */
    background-color: #fff; /* 白色背景 */
    border: 1px solid #000; /* 黑色边框 */
    border-radius: 5px; /* 圆角 */
    padding: 10px; /* 内边距 */
    box-shadow: 3px 3px 5px rgba(0, 0, 0, 0.2); /* 黑色微弱阴影 */
    outline: none; /* 去掉默认聚焦时的外边框 */
    transition: all 0.3s ease; /* 动态效果 */
}

pre {
    background-color: #f8f9fa; /* 浅灰色背景 */
    color: #333; /* 深灰色字体 */
    border: 1px solid #e0e0e0; /* 浅灰色边框 */
    border-radius: 4px; /* 圆角 */
    padding: 8px; /* 内边距 */
    font-family: 'Courier New', monospace; /* 等宽字体 */
    font-size: 14px; /* 字体大小 */
    overflow: auto; /* 长内容滚动 */
}

code {
    background-color: #E6E6E6; /* 灰色背景 */
    color: #000000; /* 黑色文字 */
    font-family: inherit; /* 使用全局字体 */
    border: 1px solid #000000; /* 浅蓝色边框 */
}

/* 父容器 */
.parent-container {
    background-color: transparent !important; /* 父级背景透明 */
}

/* 代码块样式 */
pre {
    position: relative; /* 确保可以定位子元素 */
    background-color: #E6E6E6 !important; /* 浅蓝色背景 */
    color: #000000 !important; /* 黑色文字 */
    border: none !important; /* 去掉边框 */
    box-shadow: none !important; /* 去掉阴影 */
    padding: 12px; /* 内边距 */
    margin: 10px 0; /* 上下间距 */
    overflow: hidden; /* 防止内容溢出 */
}



/* 子代码块 */
pre code {
    background-color: inherit !important; /* 继承父级背景色 */
    color: inherit !important; /* 继承文字颜色 */
    font-family: inherit; /* 全局字体 */
}


/* 聊天框字体加粗 */
.chat-message, .mes_text, .chat-container {
    font-weight: 300 !important;
}

@media screen and (max-width: 720px) {
    .mesAvatarWrapper {
        width: 0px;
        display: none;
    }
    .last_mes .mes_text {
        padding-right: 0px;
    }
    .mes_text {
        padding-bottom: 45px;
    }
}

/* 聊天消息容器整体居中布局 */
.mes {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 10px 0 20px 0; /* 控制每条消息整体上下间距 */
}

/* 聊天气泡容器，控制宽度和居中对齐 */
.mes_block {
  max-width: 90%;
  width: 100%;
  margin: 0 auto;
  text-align: left;
}

/* 头像容器：整体下移（关键） */
.mesAvatarWrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin-top: 100px;   /* 调整这个数值控制下移程度 */
  margin-bottom: 10px;
}

/* 美化头像：圆形、阴影、大小控制 */
.mesAvatarWrapper .avatar img {
  border-radius: 50%;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
  width: 56px;
  height: 56px;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.6);
}

/* 信息类（楼层、计时、token）设置为 inline，颜色继承 */
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: inline-block;
  color: var(--text-color-sec);
  font-size: 12px;
  opacity: 0.75;
  margin: 2px 4px;
  font-family: 'ZhuqueFangsong', serif;
}

/* 信息条（放在头像上或下都行） */
.mes_info_bar {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-color-sec);
  font-family: 'ZhuqueFangsong', serif;
  opacity: 0.75;
  margin-bottom: 6px;
}

/* 移动端保持一致布局 */
@media screen and (max-width: 768px) {
  .mesAvatarWrapper {
    margin-top: 0px; /* 移动端也一起下移 */
    margin-bottom: 8px;
    width: auto;
  }
  .mes_block {
    max-width: 95%;
  }
}


:root {
  --text-token-layout: contents;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: var(--text-token-layout);
  color: var(--text-color-sec);
}

/* 消息整体间距压缩 */
.mes {
  margin-bottom: 6px;
}

/* 消息文本紧凑 */
.mes_text {
  margin: 0;
  padding: 0;
  line-height: 1.5;
}

.drawer-icon {
  width: 28px;
  height: 28px;
  font-size: 24px;
  line-height: 28px;
  color: #000000;
  background: none !important;
  text-shadow: none !important;
  -webkit-background-clip: unset;
  -webkit-text-fill-color: unset;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  padding: 0;
  margin: 6px 6px 3px 3px; /* ← 重点：顶部 6px，底部 2px，下移整体位置 */
  border-radius: 6px;
  user-select: none;
  flex-shrink: 0;
  transition: background-color 0.2s ease;
}

/* 悬停效果 */
.drawer-icon:hover {
  background-color: #f2f2f2;
  cursor: pointer;
}

/* 水平对齐控制 */
.drawer-icon.left {
  margin-left: 0;
  margin-right: auto;
}

.drawer-icon.right {
  margin-left: auto;
  margin-right: 0;
}

/* 垂直对齐控制 */
.drawer-icon.top {
  align-self: flex-start;
}

.drawer-icon.bottom {
  align-self: flex-end;
}

#options_button,
#extensionsMenuButton,
#send_but {
  font-size: 18px; /* 缩小内部图标大小（用于SVG字体图标） */
  background-size: 60% 60%; /* 缩小背景图图标 */
  background-position: center;
  background-repeat: no-repeat;
}

/* 滚动条整体宽度（细） */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

/* 滚动条滑块（深灰） */
::-webkit-scrollbar-thumb {
  background: #2a2a2a; /* 更深的灰色 */
  border-radius: 10px;
  border: 1px solid #1a1a1a; /* 更暗边框，增强对比 */
}

pre {
  background-color: #f0f0f0;               /* 柔和浅灰背景 */
  color: #2c2c2c;                          /* 深灰文本，清晰可读 */
  border: 1px solid #d0d0d0;              /* 稍显边界感 */
  border-radius: 10px;
  padding: 14px 18px;
  margin: 16px 0;
  font-family: 'ZhuqueFangsong', serif;
  font-size: 13px;
  line-height: 1.65;
  position: relative;
  overflow-x: auto;
  box-shadow:
    inset 0 0 6px rgba(180, 180, 180, 0.2),
    0 0 8px rgba(200, 200, 200, 0.15);
  transition: box-shadow 0.4s ease, transform 0.3s ease;
}

pre:hover {
  box-shadow:
    inset 0 0 8px rgba(160, 160, 160, 0.3),
    0 0 12px rgba(180, 180, 180, 0.2);
  transform: translateY(-1px);
}

pre code {
  background-color: transparent !important;
  color: #3a3a3a !important;              /* 更淡的文字灰，适合浅灰背景 */
  font-family: 'Courier New', monospace;
  font-size: 13px;
  line-height: 1.65;
  display: block;
  white-space: pre-wrap;
  word-break: break-word;
  padding-left: 14px;
  border-left: 2px solid #c4c4c4;        /* 灰白分隔线 */
  position: relative;
  animation: codeFadeIn 0.4s ease;
}

pre::before {
  content: "❇️";
  position: absolute;
  top: 8px;
  left: 12px;
  font-size: 14px;
  color: rgba(100, 100, 100, 0.2);       /* 低饱和提示符 */
}

@keyframes codeFadeIn {
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: translateY(0); }
}

pre code {
  font-family: 'ZhuqueFangsong', serif;
  background-color: #e6e6e6;             /* 轻浅灰，突出代码块本身 */
}

/* ===== 固定间距系统 ===== */
/* 消息整体容器 */
.mes {
  margin-bottom: 10px !important; /* 固定消息间距 */
}

/* 头部容器 */
.mesAvatarWrapper {
  padding: 12px 15px !important; /* 固定内间距 */
  margin-bottom: 0 !important;
}

/* 消息内容区块 */
.mes_block {
  margin-top: -1px !important; /* 消除间隙 */
  padding: 12px 15px !important; /* 匹配头部间距 */
}
